CREATE TABLE IF NOT EXISTS campaigns(id TEXT PRIMARY KEY,name TEXT NOT NULL,owner TEXT,segment TEXT,objective TEXT,status TEXT,budget REAL CHECK(budget>=0),spend REAL CHECK(spend>=0),expected REAL CHECK(expected>=0),hours REAL CHECK(hours>=0),bet_index INTEGER,signal REAL,sample INTEGER,guardrail INTEGER,weeks TEXT);
CREATE TABLE IF NOT EXISTS tasks(id TEXT PRIMARY KEY,campaign_id TEXT REFERENCES campaigns(id),title TEXT NOT NULL,owner TEXT,priority TEXT,deadline TEXT,status TEXT,impact TEXT,criteria TEXT,insight TEXT DEFAULT '');
CREATE TABLE IF NOT EXISTS settings(id INTEGER PRIMARY KEY CHECK(id=1),value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS outcomes(person_key TEXT PRIMARY KEY,campaign_id TEXT REFERENCES campaigns(id),verified INTEGER CHECK(verified IN(0,1)));
CREATE TABLE IF NOT EXISTS audit(id INTEGER PRIMARY KEY AUTOINCREMENT,at TEXT DEFAULT CURRENT_TIMESTAMP,action TEXT,entity TEXT,payload TEXT);
CREATE TABLE IF NOT EXISTS experiments(id TEXT PRIMARY KEY,campaign_id TEXT NOT NULL UNIQUE REFERENCES campaigns(id),hypothesis TEXT NOT NULL,method TEXT NOT NULL,metric TEXT NOT NULL,minimum_sample INTEGER NOT NULL CHECK(minimum_sample>=0),signal REAL,sample INTEGER NOT NULL DEFAULT 0 CHECK(sample>=0),guardrail INTEGER NOT NULL DEFAULT 1 CHECK(guardrail IN(0,1)),status TEXT NOT NULL DEFAULT 'Planned');
CREATE TABLE IF NOT EXISTS scenarios(id TEXT PRIMARY KEY,name TEXT NOT NULL,settings_json TEXT NOT NULL,campaigns_json TEXT NOT NULL,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE VIEW IF NOT EXISTS verified_external_admissions AS SELECT c.* FROM checkins c JOIN people p USING(person_id) CROSS JOIN event e WHERE p.person_type='external' AND c.result='admitted' AND c.verification='verified' AND c.occurred_at BETWEEN e.event_starts_at AND e.event_ends_at;
